-- Role Quest — full setup in one script (all 9 migrations, in order).
-- Paste into Supabase → SQL Editor → Run. Atomic: if anything fails, nothing is applied.
-- Generated by scripts/build-sql.mjs from supabase/migrations/*.sql — edit those, not this file.

begin;

-- ===== 20261105000000_initial_schema.sql =====

-- Role Quest — initial schema.
--
-- Mirrors the app's repository contracts (src/repositories/contracts.ts).
-- Access rules are Row Level Security policies that mirror src/lib/permissions.ts:
-- the database is the source of truth; the services' checks are a first line.
--
-- Ids are text so they match the app's prefixed ids; new rows get a UUID.
-- Nested domain objects (sheets, map documents, system templates…) are jsonb.


-- ---------------------------------------------------------------------------
-- Profiles (one per auth user)
-- ---------------------------------------------------------------------------

create table public.profiles (
  id text primary key,
  email text not null,
  display_name text not null check (char_length(display_name) between 1 and 60),
  username text not null unique check (username ~ '^[a-z0-9._-]{2,40}$'),
  avatar_url text,
  avatar_color text not null default 'oklch(0.62 0.16 300)',
  bio text not null default '' check (char_length(bio) <= 500),
  play_style text not null default 'both' check (play_style in ('game_master', 'player', 'both')),
  favorite_system_ids text[] not null default '{}',
  timezone text not null default 'America/Sao_Paulo',
  onboarding_completed boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Campaigns and their people
-- ---------------------------------------------------------------------------

create table public.campaigns (
  id text primary key default gen_random_uuid()::text,
  name text not null check (char_length(name) between 3 and 60),
  tagline text not null default '' check (char_length(tagline) <= 160),
  system_id text not null,
  visual_style_id text not null,
  status text not null default 'planning' check (status in ('planning', 'active', 'paused', 'completed')),
  owner_id text not null references public.profiles (id) on delete cascade,
  world jsonb not null default '{}'::jsonb,
  game_master jsonb not null default '{}'::jsonb,
  player_policy jsonb not null default '{}'::jsonb,
  last_played_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.campaign_members (
  campaign_id text not null references public.campaigns (id) on delete cascade,
  user_id text not null references public.profiles (id) on delete cascade,
  role text not null check (role in ('game_master', 'player')),
  character_id text,
  joined_at timestamptz not null default now(),
  primary key (campaign_id, user_id)
);
create index campaign_members_user_idx on public.campaign_members (user_id);

create table public.game_sessions (
  id text primary key default gen_random_uuid()::text,
  campaign_id text not null references public.campaigns (id) on delete cascade,
  number integer not null check (number >= 1),
  title text not null,
  status text not null default 'scheduled' check (status in ('scheduled', 'live', 'completed', 'cancelled')),
  scheduled_at timestamptz not null,
  duration_minutes integer not null default 180,
  summary text not null default '',
  highlights text[] not null default '{}',
  attendee_ids text[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index game_sessions_campaign_idx on public.game_sessions (campaign_id);

create table public.campaign_invites (
  id text primary key default gen_random_uuid()::text,
  campaign_id text not null references public.campaigns (id) on delete cascade,
  campaign_name text not null,
  system_id text not null,
  invited_by_id text not null references public.profiles (id) on delete cascade,
  invited_by_name text not null,
  email text not null check (email = lower(email)),
  message text not null default '' check (char_length(message) <= 400),
  status text not null default 'pending' check (status in ('pending', 'accepted', 'declined', 'revoked')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index campaign_invites_campaign_idx on public.campaign_invites (campaign_id);
create index campaign_invites_email_idx on public.campaign_invites (email);

-- ---------------------------------------------------------------------------
-- Characters, systems, library
-- ---------------------------------------------------------------------------

create table public.characters (
  id text primary key default gen_random_uuid()::text,
  owner_id text not null references public.profiles (id) on delete cascade,
  campaign_id text references public.campaigns (id) on delete set null,
  system_id text not null,
  name text not null check (char_length(name) between 1 and 50),
  concept text not null default '',
  level integer,
  portrait_color text not null,
  avatar_url text,
  resources jsonb not null default '[]'::jsonb,
  tags text[] not null default '{}',
  sheet jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index characters_owner_idx on public.characters (owner_id);
create index characters_campaign_idx on public.characters (campaign_id);

alter table public.campaign_members
  add constraint campaign_members_character_fk foreign key (character_id) references public.characters (id) on delete set null;

create table public.custom_systems (
  id text primary key check (id like 'custom\_%'),
  owner_id text not null references public.profiles (id) on delete cascade,
  system jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index custom_systems_owner_idx on public.custom_systems (owner_id);

create table public.library_assets (
  id text primary key default gen_random_uuid()::text,
  owner_id text not null references public.profiles (id) on delete cascade,
  kind text not null check (kind in ('scenario', 'resource')),
  title text not null,
  description text not null default '',
  biome text,
  category text,
  tags text[] not null default '{}',
  system_ids text[] not null default '{}',
  item_count integer not null default 0,
  preview_gradient text[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- GM tools and maps
-- ---------------------------------------------------------------------------

create table public.saved_maps (
  id text primary key,
  campaign_id text not null references public.campaigns (id) on delete cascade,
  name text not null,
  created_by text not null references public.profiles (id) on delete cascade,
  document jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index saved_maps_campaign_idx on public.saved_maps (campaign_id);

create table public.npcs (
  id text primary key default gen_random_uuid()::text,
  campaign_id text not null references public.campaigns (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 60),
  concept text not null default '',
  attitude text not null default 'neutral' check (attitude in ('ally', 'neutral', 'hostile')),
  portrait_color text not null,
  model_id text,
  location text not null default '',
  description text not null default '',
  secret_notes text not null default '',
  facts jsonb not null default '[]'::jsonb,
  stats jsonb not null,
  known boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index npcs_campaign_idx on public.npcs (campaign_id);

create table public.encounters (
  id text primary key default gen_random_uuid()::text,
  campaign_id text not null references public.campaigns (id) on delete cascade,
  name text not null,
  description text not null default '',
  entries jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index encounters_campaign_idx on public.encounters (campaign_id);

create table public.journal_entries (
  id text primary key default gen_random_uuid()::text,
  campaign_id text not null references public.campaigns (id) on delete cascade,
  at timestamptz not null,
  session_label text not null,
  kind text not null check (kind in ('combat', 'down', 'trap', 'epic', 'critical', 'reveal', 'map', 'note')),
  text text not null check (char_length(text) between 1 and 500),
  private boolean not null default false,
  source_id text,
  dismissed boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (campaign_id, source_id)
);
create index journal_entries_campaign_idx on public.journal_entries (campaign_id);

-- ---------------------------------------------------------------------------
-- updated_at
-- ---------------------------------------------------------------------------

create function public.touch_updated_at() returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['profiles', 'campaigns', 'game_sessions', 'campaign_invites', 'characters', 'custom_systems', 'library_assets', 'saved_maps', 'npcs', 'encounters', 'journal_entries'] loop
    execute format('create trigger %I_touch before update on public.%I for each row execute function public.touch_updated_at()', t, t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Permission helpers (security definer: they read membership without
-- recursing into the policies that use them)
-- ---------------------------------------------------------------------------

create function public.me() returns text language sql stable as $$ select auth.uid()::text $$;

create function public.my_email() returns text language sql stable as $$ select lower(coalesce(auth.jwt() ->> 'email', '')) $$;

create function public.is_member(cid text) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from campaign_members where campaign_id = cid and user_id = auth.uid()::text)
$$;

create function public.is_gm(cid text) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from campaign_members where campaign_id = cid and user_id = auth.uid()::text and role = 'game_master')
$$;

create function public.is_owner(cid text) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from campaigns where id = cid and owner_id = auth.uid()::text)
$$;

create function public.shares_campaign(other text) returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from campaign_members a join campaign_members b on a.campaign_id = b.campaign_id
    where a.user_id = auth.uid()::text and b.user_id = other
  )
$$;

create function public.has_pending_invite(cid text) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from campaign_invites where campaign_id = cid and email = public.my_email() and status = 'pending')
$$;

-- ---------------------------------------------------------------------------
-- New users get a profile (display name from sign-up metadata, unique username)
-- ---------------------------------------------------------------------------

create function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$
declare
  base text := regexp_replace(lower(split_part(new.email, '@', 1)), '[^a-z0-9._-]', '.', 'g');
  candidate text;
  n integer := 1;
  colors text[] := array['oklch(0.62 0.16 30)', 'oklch(0.62 0.14 70)', 'oklch(0.6 0.13 150)', 'oklch(0.6 0.13 230)', 'oklch(0.6 0.15 300)', 'oklch(0.62 0.15 340)'];
begin
  if char_length(base) < 2 then base := 'aventureiro'; end if;
  base := left(base, 34);
  candidate := base;
  while exists (select 1 from profiles where username = candidate) loop
    n := n + 1;
    candidate := base || n;
  end loop;
  insert into profiles (id, email, display_name, username, avatar_color)
  values (
    new.id::text,
    lower(new.email),
    left(coalesce(nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''), base), 60),
    candidate,
    colors[1 + (abs(hashtext(new.id::text)) % array_length(colors, 1))]
  );
  return new;
end $$;

create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

-- Username availability without exposing other profiles.
create function public.username_taken(candidate text, except_user text default null) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from profiles where username = candidate and id is distinct from except_user)
$$;

-- ---------------------------------------------------------------------------
-- Campaign rules the policies can't express on their own
-- ---------------------------------------------------------------------------

-- The creator joins as GM.
create function public.add_owner_as_gm() returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into campaign_members (campaign_id, user_id, role) values (new.id, new.owner_id, 'game_master');
  return new;
end $$;
create trigger campaigns_owner_member after insert on public.campaigns for each row execute function public.add_owner_as_gm();

-- Only the creator changes roles; the creator stays GM; a member links only their own character.
create function public.guard_member_update() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.campaign_id <> old.campaign_id or new.user_id <> old.user_id then
    raise exception 'Membro não pode mudar de campanha.' using errcode = '42501';
  end if;
  if new.role <> old.role then
    if not public.is_owner(new.campaign_id) then
      raise exception 'Só quem criou a campanha muda os papéis.' using errcode = '42501';
    end if;
    if new.user_id = (select owner_id from campaigns where id = new.campaign_id) and new.role <> 'game_master' then
      raise exception 'Quem criou a campanha continua mestre.' using errcode = '42501';
    end if;
  end if;
  if new.character_id is distinct from old.character_id and new.character_id is not null
     and not exists (select 1 from characters where id = new.character_id and owner_id = new.user_id) then
    raise exception 'O personagem precisa ser de quem o vincula.' using errcode = '42501';
  end if;
  return new;
end $$;
create trigger campaign_members_guard before update on public.campaign_members for each row execute function public.guard_member_update();

-- The creator is never removed, and a campaign always keeps a GM.
create function public.guard_member_delete() returns trigger language plpgsql security definer set search_path = public as $$
begin
  -- Cascades from a deleted campaign/profile are fine.
  if not exists (select 1 from campaigns where id = old.campaign_id) then return old; end if;
  if old.user_id = (select owner_id from campaigns where id = old.campaign_id) then
    raise exception 'Quem criou a campanha não pode ser removido.' using errcode = '42501';
  end if;
  return old;
end $$;
create trigger campaign_members_guard_delete before delete on public.campaign_members for each row execute function public.guard_member_delete();

-- Accepting an invite: atomically checks the e-mail, the status and the free seats.
create function public.accept_invite(invite_id text) returns void language plpgsql security definer set search_path = public as $$
declare
  inv campaign_invites;
  seats integer;
  taken integer;
begin
  select * into inv from campaign_invites where id = invite_id for update;
  if inv.id is null or inv.email <> public.my_email() then raise exception 'Convite não encontrado.' using errcode = 'P0002'; end if;
  if inv.status <> 'pending' then raise exception 'Este convite já foi respondido.' using errcode = '22023'; end if;
  select (player_policy ->> 'maxPlayers')::integer into seats from campaigns where id = inv.campaign_id for update;
  select count(*) into taken from campaign_members where campaign_id = inv.campaign_id and role = 'player';
  if taken >= coalesce(seats, 0) then raise exception 'A campanha já está com todas as vagas preenchidas.' using errcode = '22023'; end if;
  insert into campaign_members (campaign_id, user_id, role) values (inv.campaign_id, auth.uid()::text, 'player')
    on conflict (campaign_id, user_id) do nothing;
  update campaign_invites set status = 'accepted' where id = invite_id;
end $$;

-- ---------------------------------------------------------------------------
-- Reads that strip secrets
-- ---------------------------------------------------------------------------

-- The party of a campaign: full rows for your own characters (and all of them
-- for the GM); for other players' characters, no sheet (private notes live there).
create function public.campaign_characters(cid text) returns setof public.characters language sql stable security definer set search_path = public as $$
  select c.id, c.owner_id, c.campaign_id, c.system_id, c.name, c.concept, c.level, c.portrait_color, c.avatar_url, c.resources, c.tags,
         case when c.owner_id = auth.uid()::text or public.is_gm(cid) then c.sheet else null end,
         c.created_at, c.updated_at
  from characters c
  where c.campaign_id = cid and public.is_member(cid)
$$;

-- NPCs the party knows: public fields and revealed facts only.
create function public.known_npcs(cid text) returns setof public.npcs language sql stable security definer set search_path = public as $$
  select n.id, n.campaign_id, n.name, n.concept, 'neutral'::text, n.portrait_color, null::text, n.location, n.description, ''::text,
         coalesce((select jsonb_agg(f) from jsonb_array_elements(n.facts) f where coalesce((f ->> 'revealed')::boolean, false)), '[]'::jsonb),
         '{}'::jsonb, true, n.created_at, n.updated_at
  from npcs n
  where n.campaign_id = cid and n.known and public.is_member(cid)
$$;

-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------

alter table public.profiles enable row level security;
alter table public.campaigns enable row level security;
alter table public.campaign_members enable row level security;
alter table public.game_sessions enable row level security;
alter table public.campaign_invites enable row level security;
alter table public.characters enable row level security;
alter table public.custom_systems enable row level security;
alter table public.library_assets enable row level security;
alter table public.saved_maps enable row level security;
alter table public.npcs enable row level security;
alter table public.encounters enable row level security;
alter table public.journal_entries enable row level security;

-- Profiles: yourself and the people you play with.
create policy profiles_read on public.profiles for select to authenticated using (id = public.me() or public.shares_campaign(id));
create policy profiles_update on public.profiles for update to authenticated using (id = public.me()) with check (id = public.me());

-- Campaigns: members read; GMs edit; the creator deletes.
create policy campaigns_read on public.campaigns for select to authenticated using (public.is_member(id) or owner_id = public.me());
create policy campaigns_insert on public.campaigns for insert to authenticated with check (owner_id = public.me());
create policy campaigns_update on public.campaigns for update to authenticated using (public.is_gm(id)) with check (public.is_gm(id));
create policy campaigns_delete on public.campaigns for delete to authenticated using (owner_id = public.me());

-- Members: GMs add people; the creator changes roles (trigger); a member edits
-- their own row (character link only, trigger); GMs remove players, the creator removes GMs.
create policy members_read on public.campaign_members for select to authenticated using (public.is_member(campaign_id));
create policy members_insert on public.campaign_members for insert to authenticated with check (public.is_gm(campaign_id));
create policy members_update on public.campaign_members for update to authenticated
  using (public.is_owner(campaign_id) or user_id = public.me())
  with check (public.is_owner(campaign_id) or user_id = public.me());
create policy members_delete on public.campaign_members for delete to authenticated
  using (public.is_owner(campaign_id) or (public.is_gm(campaign_id) and role = 'player' and user_id <> public.me()));

-- Sessions: members read; GMs write.
create policy sessions_read on public.game_sessions for select to authenticated using (public.is_member(campaign_id));
create policy sessions_write on public.game_sessions for all to authenticated using (public.is_gm(campaign_id)) with check (public.is_gm(campaign_id));

-- Invites: GMs manage theirs; the invitee sees and declines (accepting goes through accept_invite).
create policy invites_read on public.campaign_invites for select to authenticated using (public.is_gm(campaign_id) or email = public.my_email());
create policy invites_insert on public.campaign_invites for insert to authenticated with check (public.is_gm(campaign_id) and invited_by_id = public.me());
create policy invites_update on public.campaign_invites for update to authenticated
  using (public.is_gm(campaign_id) or email = public.my_email())
  with check (public.is_gm(campaign_id) or (email = public.my_email() and status = 'declined'));

-- Characters: the owner, and the GM of the character's campaign. Other members
-- see the party through campaign_characters() (without sheets).
create policy characters_read on public.characters for select to authenticated using (owner_id = public.me() or (campaign_id is not null and public.is_gm(campaign_id)));
create policy characters_insert on public.characters for insert to authenticated with check (owner_id = public.me() and (campaign_id is null or public.is_member(campaign_id)));
create policy characters_update on public.characters for update to authenticated
  using (owner_id = public.me() or (campaign_id is not null and public.is_gm(campaign_id)))
  with check (owner_id = public.me() or campaign_id is null or public.is_gm(campaign_id));
create policy characters_delete on public.characters for delete to authenticated using (owner_id = public.me());

-- Custom systems: the owner edits; members of campaigns that use one can read it.
create policy systems_read on public.custom_systems for select to authenticated using (
  owner_id = public.me()
  or exists (select 1 from public.campaigns c where c.system_id = custom_systems.id and public.is_member(c.id))
);
create policy systems_write on public.custom_systems for all to authenticated using (owner_id = public.me()) with check (owner_id = public.me());

-- Library: personal.
create policy library_owner on public.library_assets for all to authenticated using (owner_id = public.me()) with check (owner_id = public.me());

-- Maps, NPCs, encounters: GM only (players get known NPCs through known_npcs()).
create policy maps_gm on public.saved_maps for all to authenticated using (public.is_gm(campaign_id)) with check (public.is_gm(campaign_id));
create policy npcs_gm on public.npcs for all to authenticated using (public.is_gm(campaign_id)) with check (public.is_gm(campaign_id));
create policy encounters_gm on public.encounters for all to authenticated using (public.is_gm(campaign_id)) with check (public.is_gm(campaign_id));

-- Journal: GMs everything; players the public, not-dismissed entries.
create policy journal_read on public.journal_entries for select to authenticated using (
  public.is_gm(campaign_id) or (public.is_member(campaign_id) and not private and not dismissed)
);
create policy journal_write on public.journal_entries for all to authenticated using (public.is_gm(campaign_id)) with check (public.is_gm(campaign_id));

-- Functions callable by signed-in users only.
revoke execute on function public.accept_invite(text), public.campaign_characters(text), public.known_npcs(text), public.username_taken(text, text) from public, anon;
grant execute on function public.accept_invite(text), public.campaign_characters(text), public.known_npcs(text), public.username_taken(text, text) to authenticated;


-- ===== 20261105000100_access_hardening.sql =====

-- Role Quest — access hardening.
--
-- Closes paths found in review: ownership changes (campaigns, characters),
-- GMs adding people without an invite, GM notes readable by players, custom
-- systems readable through someone else's campaign, characters moved into
-- campaigns their owner doesn't play in, profile e-mail rewrites, invite edits.
--
-- Guards skip writes made inside our security-definer functions (they run as
-- the function owner, not as `authenticated`/`anon`), e.g. accept_invite.

create function public.is_api_role() returns boolean language sql stable as $$
  select current_user in ('authenticated', 'anon')
$$;

-- ---------------------------------------------------------------------------
-- GM notes: own table, GMs only (the campaign row is readable by every member)
-- ---------------------------------------------------------------------------

create table public.campaign_gm_notes (
  campaign_id text primary key references public.campaigns (id) on delete cascade,
  notes text not null default '' check (char_length(notes) <= 1000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger campaign_gm_notes_touch before update on public.campaign_gm_notes for each row execute function public.touch_updated_at();
alter table public.campaign_gm_notes enable row level security;
create policy gm_notes_gm on public.campaign_gm_notes for all to authenticated using (public.is_gm(campaign_id)) with check (public.is_gm(campaign_id));

insert into public.campaign_gm_notes (campaign_id, notes)
  select id, game_master ->> 'notes' from public.campaigns where coalesce(game_master ->> 'notes', '') <> '';
update public.campaigns set game_master = game_master - 'notes' where game_master ? 'notes';

-- ---------------------------------------------------------------------------
-- Campaigns: the owner never changes; GM notes never land in the shared row
-- ---------------------------------------------------------------------------

create function public.guard_campaign_write() returns trigger language plpgsql set search_path = public as $$
begin
  if tg_op = 'UPDATE' and (new.id <> old.id or new.owner_id <> old.owner_id) then
    raise exception 'A campanha não muda de dono.' using errcode = '42501';
  end if;
  new.game_master := coalesce(new.game_master, '{}'::jsonb) - 'notes';
  return new;
end $$;
create trigger campaigns_guard before insert or update on public.campaigns for each row execute function public.guard_campaign_write();

-- ---------------------------------------------------------------------------
-- Members: nobody inserts directly. People join through accept_invite; the
-- creator through the campaign trigger.
-- ---------------------------------------------------------------------------

drop policy members_insert on public.campaign_members;

-- The linked character must be the member's own, and already in this campaign.
create or replace function public.guard_member_update() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.campaign_id <> old.campaign_id or new.user_id <> old.user_id then
    raise exception 'Membro não pode mudar de campanha.' using errcode = '42501';
  end if;
  if new.role <> old.role then
    if not public.is_owner(new.campaign_id) then
      raise exception 'Só quem criou a campanha muda os papéis.' using errcode = '42501';
    end if;
    if new.user_id = (select owner_id from campaigns where id = new.campaign_id) and new.role <> 'game_master' then
      raise exception 'Quem criou a campanha continua mestre.' using errcode = '42501';
    end if;
  end if;
  if new.character_id is distinct from old.character_id and new.character_id is not null
     and not exists (select 1 from characters where id = new.character_id and owner_id = new.user_id and campaign_id = new.campaign_id) then
    raise exception 'O personagem precisa ser de quem o vincula e estar nesta campanha.' using errcode = '42501';
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- Characters: the owner never changes; only the owner moves a character into
-- a campaign (one they play in); a GM can only take it out (removing a player).
-- ---------------------------------------------------------------------------

create function public.guard_character_update() returns trigger language plpgsql set search_path = public as $$
begin
  if not public.is_api_role() then return new; end if;
  if new.id <> old.id or new.owner_id <> old.owner_id then
    raise exception 'O personagem não muda de dono.' using errcode = '42501';
  end if;
  if new.campaign_id is distinct from old.campaign_id and new.campaign_id is not null
     and (old.owner_id <> public.me() or not public.is_member(new.campaign_id)) then
    raise exception 'Só quem joga na campanha leva um personagem para ela.' using errcode = '42501';
  end if;
  return new;
end $$;
create trigger characters_guard before update on public.characters for each row execute function public.guard_character_update();

-- The party: characters of current members only.
create or replace function public.campaign_characters(cid text) returns setof public.characters language sql stable security definer set search_path = public as $$
  select c.id, c.owner_id, c.campaign_id, c.system_id, c.name, c.concept, c.level, c.portrait_color, c.avatar_url, c.resources, c.tags,
         case when c.owner_id = auth.uid()::text or public.is_gm(cid) then c.sheet else null end,
         c.created_at, c.updated_at
  from characters c
  where c.campaign_id = cid and public.is_member(cid)
    and exists (select 1 from campaign_members m where m.campaign_id = cid and m.user_id = c.owner_id)
  order by c.created_at
$$;

create or replace function public.known_npcs(cid text) returns setof public.npcs language sql stable security definer set search_path = public as $$
  select n.id, n.campaign_id, n.name, n.concept, 'neutral'::text, n.portrait_color, null::text, n.location, n.description, ''::text,
         coalesce((select jsonb_agg(f) from jsonb_array_elements(n.facts) f where coalesce((f ->> 'revealed')::boolean, false)), '[]'::jsonb),
         '{}'::jsonb, true, n.created_at, n.updated_at
  from npcs n
  where n.campaign_id = cid and n.known and public.is_member(cid)
  order by n.name
$$;

-- ---------------------------------------------------------------------------
-- Custom systems: readable by members (and invitees) of campaigns whose
-- creator owns the system — not through any campaign that names its id.
-- ---------------------------------------------------------------------------

create function public.can_read_system(sid text, sowner text) returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from campaigns c
    where c.system_id = sid and c.owner_id = sowner and (public.is_member(c.id) or public.has_pending_invite(c.id))
  )
$$;

drop policy systems_read on public.custom_systems;
create policy systems_read on public.custom_systems for select to authenticated using (owner_id = public.me() or public.can_read_system(id, owner_id));

-- ---------------------------------------------------------------------------
-- Invites: the invitee only declines a pending one; nobody moves an invite.
-- ---------------------------------------------------------------------------

create function public.guard_invite_update() returns trigger language plpgsql set search_path = public as $$
begin
  if not public.is_api_role() then return new; end if;
  if new.campaign_id <> old.campaign_id or new.email <> old.email then
    raise exception 'O convite não muda de campanha nem de destinatário.' using errcode = '42501';
  end if;
  if public.is_gm(old.campaign_id) then return new; end if;
  if old.status <> 'pending' or new.status <> 'declined'
     or (new.campaign_name, new.system_id, new.invited_by_id, new.invited_by_name, new.message)
        is distinct from (old.campaign_name, old.system_id, old.invited_by_id, old.invited_by_name, old.message) then
    raise exception 'Você só pode recusar um convite pendente.' using errcode = '42501';
  end if;
  return new;
end $$;
create trigger campaign_invites_guard before update on public.campaign_invites for each row execute function public.guard_invite_update();

-- ---------------------------------------------------------------------------
-- Profiles: id and e-mail come from Auth; usernames follow the app's rule.
-- ---------------------------------------------------------------------------

create function public.guard_profile_update() returns trigger language plpgsql set search_path = public as $$
begin
  if public.is_api_role() and (new.id <> old.id or new.email <> old.email) then
    raise exception 'O e-mail da conta não muda pelo perfil.' using errcode = '42501';
  end if;
  return new;
end $$;
create trigger profiles_guard before update on public.profiles for each row execute function public.guard_profile_update();

-- Same rule as USERNAME_PATTERN in src/services/profile.service.ts (existing rows are kept).
alter table public.profiles drop constraint profiles_username_check;
alter table public.profiles add constraint profiles_username_check check (username ~ '^[a-z0-9._]{3,20}$') not valid;

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$
declare
  base text := left(regexp_replace(lower(split_part(coalesce(new.email, ''), '@', 1)), '[^a-z0-9._]', '.', 'g'), 16);
  candidate text;
  n integer := 1;
  colors text[] := array['oklch(0.62 0.16 30)', 'oklch(0.62 0.14 70)', 'oklch(0.6 0.13 150)', 'oklch(0.6 0.13 230)', 'oklch(0.6 0.15 300)', 'oklch(0.62 0.15 340)'];
begin
  if char_length(base) < 3 then base := 'aventureiro'; end if;
  candidate := base;
  while exists (select 1 from profiles where username = candidate) loop
    n := n + 1;
    candidate := base || n;
  end loop;
  insert into profiles (id, email, display_name, username, avatar_color)
  values (
    new.id::text,
    lower(coalesce(new.email, '')),
    left(coalesce(nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''), base), 60),
    candidate,
    colors[1 + (abs(hashtext(new.id::text)) % array_length(colors, 1))]
  );
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- Membership helpers: signed-in users only (the policies call them as `authenticated`).
-- ---------------------------------------------------------------------------

revoke execute on function
  public.is_member(text), public.is_gm(text), public.is_owner(text),
  public.shares_campaign(text), public.has_pending_invite(text), public.can_read_system(text, text)
from public, anon;
grant execute on function
  public.is_member(text), public.is_gm(text), public.is_owner(text),
  public.shares_campaign(text), public.has_pending_invite(text), public.can_read_system(text, text)
to authenticated;


-- ===== 20261105000200_invite_links.sql =====

-- Role Quest — invite links replace e-mail invites.
--
-- The GM shares a link (a random code) anywhere; whoever opens it signed in
-- joins as a player while there are free seats. The GM can replace the code
-- (old links stop working) or turn the link off. No e-mail involved.

-- ---------------------------------------------------------------------------
-- Out: e-mail invites
-- ---------------------------------------------------------------------------

drop function public.accept_invite(text);
drop table public.campaign_invites;
drop function public.guard_invite_update();

-- Custom systems: members of the owner's campaigns that use them (no invitees any more).
create or replace function public.can_read_system(sid text, sowner text) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from campaigns c where c.system_id = sid and c.owner_id = sowner and public.is_member(c.id))
$$;
drop function public.has_pending_invite(text);
drop function public.my_email();

-- ---------------------------------------------------------------------------
-- In: one invite link per campaign, readable only by its GMs
-- ---------------------------------------------------------------------------

create table public.campaign_invite_links (
  campaign_id text primary key references public.campaigns (id) on delete cascade,
  -- A v4 UUID (122 random bits) without dashes; the GM never picks it.
  code text not null unique default replace(gen_random_uuid()::text, '-', ''),
  created_at timestamptz not null default now()
);
alter table public.campaign_invite_links enable row level security;
create policy invite_links_gm_read on public.campaign_invite_links for select to authenticated using (public.is_gm(campaign_id));
create policy invite_links_gm_delete on public.campaign_invite_links for delete to authenticated using (public.is_gm(campaign_id));
-- Codes come from new_invite_link() only, never from the client.

-- Campaigns created before this migration get their link too.
insert into public.campaign_invite_links (campaign_id) select id from public.campaigns on conflict do nothing;

-- Creates the campaign's link, or replaces its code (old links stop working).
create function public.new_invite_link(cid text) returns public.campaign_invite_links language plpgsql security definer set search_path = public as $$
declare
  link campaign_invite_links;
begin
  if not public.is_gm(cid) then raise exception 'Só os mestres da campanha geram o link de convite.' using errcode = '42501'; end if;
  insert into campaign_invite_links (campaign_id) values (cid)
    on conflict (campaign_id) do update set code = replace(gen_random_uuid()::text, '-', ''), created_at = now()
    returning * into link;
  return link;
end $$;

-- What the link opens, before joining: enough to decide, nothing private.
create function public.invite_preview(invite_code text)
returns table (campaign_id text, campaign_name text, tagline text, system_id text, system_name text, game_master_name text, free_seats integer, already_member boolean)
language sql stable security definer set search_path = public as $$
  select c.id, c.name, c.tagline, c.system_id,
         -- Custom systems are readable only after joining: their name comes along here.
         cs.system ->> 'name',
         coalesce(nullif(c.game_master ->> 'narratorName', ''), p.display_name),
         greatest(coalesce((c.player_policy ->> 'maxPlayers')::integer, 0) - (select count(*)::integer from campaign_members m where m.campaign_id = c.id and m.role = 'player'), 0),
         exists (select 1 from campaign_members m where m.campaign_id = c.id and m.user_id = auth.uid()::text)
  from campaign_invite_links l
  join campaigns c on c.id = l.campaign_id
  join profiles p on p.id = c.owner_id
  left join custom_systems cs on cs.id = c.system_id and cs.owner_id = c.owner_id
  where l.code = invite_code and auth.uid() is not null
$$;

-- Joining by link: atomically checks the code and the free seats. Returns the campaign id.
create function public.join_campaign(invite_code text) returns text language plpgsql security definer set search_path = public as $$
declare
  cid text;
  seats integer;
  taken integer;
begin
  if auth.uid() is null then raise exception 'Entre na sua conta para usar o convite.' using errcode = '42501'; end if;
  select l.campaign_id into cid from campaign_invite_links l where l.code = invite_code;
  if cid is null then raise exception 'Este link de convite não vale mais. Peça um novo ao mestre.' using errcode = 'P0002'; end if;
  -- Lock first: two tabs joining at once see each other.
  select (player_policy ->> 'maxPlayers')::integer into seats from campaigns where id = cid for update;
  if exists (select 1 from campaign_members where campaign_id = cid and user_id = auth.uid()::text) then return cid; end if;
  select count(*) into taken from campaign_members where campaign_id = cid and role = 'player';
  if taken >= coalesce(seats, 0) then raise exception 'A campanha já está com todas as vagas preenchidas.' using errcode = '22023'; end if;
  insert into campaign_members (campaign_id, user_id, role) values (cid, auth.uid()::text, 'player')
    on conflict (campaign_id, user_id) do nothing;
  return cid;
end $$;

revoke execute on function public.can_read_system(text, text), public.new_invite_link(text), public.invite_preview(text), public.join_campaign(text) from public, anon;
grant execute on function public.can_read_system(text, text), public.new_invite_link(text), public.invite_preview(text), public.join_campaign(text) to authenticated;


-- ===== 20261106000000_realtime_table.sql =====

-- Role Quest — the table in real time.
--
-- One GM client "hosts" the room: it holds the full state, applies every
-- change and writes, for each other member, the view they may see (players:
-- fog-filtered, no hidden traps, no GM notes or secret rolls). Players never
-- receive the full state: they read their own view row and send intents
-- (move, chat, roll, attack…), which the host validates and applies.
-- Clients follow rows through Supabase Realtime (postgres_changes, RLS applies).

-- ---------------------------------------------------------------------------
-- The room's full state (GMs only) and who hosts it
-- ---------------------------------------------------------------------------

create table public.room_states (
  campaign_id text primary key references public.campaigns (id) on delete cascade,
  state jsonb,
  revision bigint not null default 0,
  host_user text references public.profiles (id) on delete set null,
  host_client text,
  host_seen_at timestamptz,
  updated_at timestamptz not null default now()
);
create trigger room_states_touch before update on public.room_states for each row execute function public.touch_updated_at();
alter table public.room_states enable row level security;
create policy room_states_gm on public.room_states for all to authenticated using (public.is_gm(campaign_id)) with check (public.is_gm(campaign_id));

-- A GM client takes (or keeps) the host role: free, its own, stale for 90 s, or taken over.
-- (90 s: browsers slow down timers of background tabs to about once a minute.)
create function public.claim_room_host(cid text, client text, takeover boolean default false)
returns table (holder_user text, holder_client text, hosting boolean)
language plpgsql security definer set search_path = public as $$
begin
  if not public.is_gm(cid) then raise exception 'Só os mestres conduzem a mesa.' using errcode = '42501'; end if;
  insert into room_states (campaign_id) values (cid) on conflict (campaign_id) do nothing;
  update room_states r set host_user = auth.uid()::text, host_client = client, host_seen_at = now()
    where r.campaign_id = cid
      and (takeover or r.host_client is null or r.host_client = client or r.host_seen_at < now() - interval '90 seconds');
  return query select r.host_user, r.host_client, r.host_client = client from room_states r where r.campaign_id = cid;
end $$;

create function public.release_room_host(cid text, client text) returns void
language sql security definer set search_path = public as $$
  update room_states set host_client = null, host_seen_at = null where campaign_id = cid and host_client = client and public.is_gm(cid)
$$;

-- ---------------------------------------------------------------------------
-- What each member sees, written by the host
-- ---------------------------------------------------------------------------

create table public.room_views (
  campaign_id text not null references public.campaigns (id) on delete cascade,
  user_id text not null references public.profiles (id) on delete cascade,
  view jsonb not null,
  revision bigint not null default 0,
  updated_at timestamptz not null default now(),
  primary key (campaign_id, user_id)
);
alter table public.room_views enable row level security;
create policy room_views_own on public.room_views for select to authenticated using ((user_id = public.me() and public.is_member(campaign_id)) or public.is_gm(campaign_id));
create policy room_views_gm_insert on public.room_views for insert to authenticated with check (public.is_gm(campaign_id));
create policy room_views_gm_update on public.room_views for update to authenticated using (public.is_gm(campaign_id)) with check (public.is_gm(campaign_id));
create policy room_views_gm_delete on public.room_views for delete to authenticated using (public.is_gm(campaign_id));

-- The players' map (no GM notes, no hidden traps): shared, changes rarely.
create table public.room_view_maps (
  campaign_id text primary key references public.campaigns (id) on delete cascade,
  map jsonb not null,
  revision bigint not null default 0,
  updated_at timestamptz not null default now()
);
alter table public.room_view_maps enable row level security;
create policy room_view_maps_read on public.room_view_maps for select to authenticated using (public.is_member(campaign_id));
create policy room_view_maps_gm on public.room_view_maps for all to authenticated using (public.is_gm(campaign_id)) with check (public.is_gm(campaign_id));

-- Only the client that holds the lease publishes: a host that lost it (taken
-- over, or asleep) can't overwrite the new host's views. Returns false then.
create function public.publish_room(cid text, client text, views jsonb, map jsonb default null, map_revision bigint default null)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not public.is_gm(cid) then raise exception 'Só os mestres conduzem a mesa.' using errcode = '42501'; end if;
  if not exists (select 1 from room_states where campaign_id = cid and host_client = client) then return false; end if;
  if map is not null then
    insert into room_view_maps (campaign_id, map, revision) values (cid, map, coalesce(map_revision, 0))
      on conflict (campaign_id) do update set map = excluded.map, revision = excluded.revision, updated_at = now();
  end if;
  insert into room_views (campaign_id, user_id, view, revision)
    select cid, v.user_id, v.view, coalesce(v.revision, 0)
    from jsonb_to_recordset(coalesce(views, '[]'::jsonb)) as v(user_id text, view jsonb, revision bigint)
    where exists (select 1 from campaign_members m where m.campaign_id = cid and m.user_id = v.user_id)
    on conflict (campaign_id, user_id) do update set view = excluded.view, revision = excluded.revision, updated_at = now();
  return true;
end $$;

create function public.save_room_state(cid text, client text, room jsonb) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  if not public.is_gm(cid) then raise exception 'Só os mestres conduzem a mesa.' using errcode = '42501'; end if;
  update room_states set state = room, revision = revision + 1 where campaign_id = cid and host_client = client;
  return found;
end $$;

-- ---------------------------------------------------------------------------
-- What members ask the host to do
-- ---------------------------------------------------------------------------

create table public.room_intents (
  id text primary key default gen_random_uuid()::text,
  campaign_id text not null references public.campaigns (id) on delete cascade,
  user_id text not null default auth.uid()::text references public.profiles (id) on delete cascade,
  intent jsonb not null check (octet_length(intent::text) <= 20000),
  created_at timestamptz not null default now()
);
create index room_intents_campaign_idx on public.room_intents (campaign_id, created_at);
alter table public.room_intents enable row level security;
-- Members speak only for themselves; the host (a GM) reads and clears them.
create policy room_intents_insert on public.room_intents for insert to authenticated with check (user_id = public.me() and public.is_member(campaign_id));
create policy room_intents_read on public.room_intents for select to authenticated using (public.is_gm(campaign_id) or user_id = public.me());
create policy room_intents_gm_delete on public.room_intents for delete to authenticated using (public.is_gm(campaign_id));

-- Host: intents not handled yet, at most a minute old (older ones are dropped).
create function public.pending_room_intents(cid text) returns setof public.room_intents
language plpgsql security definer set search_path = public as $$
begin
  if not public.is_gm(cid) then raise exception 'Só os mestres conduzem a mesa.' using errcode = '42501'; end if;
  delete from room_intents where campaign_id = cid and created_at < now() - interval '60 seconds';
  return query select * from room_intents where campaign_id = cid order by created_at;
end $$;

-- ---------------------------------------------------------------------------
-- Who is at the table (heartbeat every few seconds)
-- ---------------------------------------------------------------------------

create table public.room_presence (
  campaign_id text not null references public.campaigns (id) on delete cascade,
  user_id text not null references public.profiles (id) on delete cascade,
  hosting boolean not null default false,
  seen_at timestamptz not null default now(),
  primary key (campaign_id, user_id)
);
alter table public.room_presence enable row level security;
create policy room_presence_read on public.room_presence for select to authenticated using (public.is_member(campaign_id));
-- Only a GM may say they host the table.
create policy room_presence_insert on public.room_presence for insert to authenticated
  with check (user_id = public.me() and public.is_member(campaign_id) and (not hosting or public.is_gm(campaign_id)));
create policy room_presence_update on public.room_presence for update to authenticated
  using (user_id = public.me())
  with check (user_id = public.me() and public.is_member(campaign_id) and (not hosting or public.is_gm(campaign_id)));
create policy room_presence_delete on public.room_presence for delete to authenticated using (user_id = public.me() or public.is_gm(campaign_id));

-- The server's clock, not each browser's, says when someone was last seen.
create function public.stamp_presence() returns trigger language plpgsql set search_path = public as $$
begin
  new.seen_at := now();
  return new;
end $$;
create trigger room_presence_stamp before insert or update on public.room_presence for each row execute function public.stamp_presence();

-- Someone who leaves the campaign leaves the table.
create function public.drop_presence_of_member() returns trigger language plpgsql security definer set search_path = public as $$
begin
  delete from room_presence where campaign_id = old.campaign_id and user_id = old.user_id;
  delete from room_views where campaign_id = old.campaign_id and user_id = old.user_id;
  return old;
end $$;
create trigger campaign_members_leave_table after delete on public.campaign_members for each row execute function public.drop_presence_of_member();

revoke execute on function public.claim_room_host(text, text, boolean), public.release_room_host(text, text), public.publish_room(text, text, jsonb, jsonb, bigint),
  public.save_room_state(text, text, jsonb), public.pending_room_intents(text) from public, anon;
grant execute on function public.claim_room_host(text, text, boolean), public.release_room_host(text, text), public.publish_room(text, text, jsonb, jsonb, bigint),
  public.save_room_state(text, text, jsonb), public.pending_room_intents(text) to authenticated;

-- Realtime: clients follow these tables (each subscriber only gets rows its RLS allows).
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table public.room_views, public.room_view_maps, public.room_intents, public.room_presence;
  end if;
end $$;


-- ===== 20261107000000_chronicles.sql =====

-- Role Quest — Chronicles Studio: episodes made from the campaign's best moments.
--
-- An episode keeps the chosen moments, the script written by AI (scenes with
-- narration, dialogue and image prompts) and the generated images (paths in
-- the private `chronicles` Storage bucket). GMs only, for now.

create table public.chronicle_episodes (
  id text primary key default gen_random_uuid()::text,
  campaign_id text not null references public.campaigns (id) on delete cascade,
  title text not null default 'Episódio' check (char_length(title) between 1 and 120),
  moment_ids text[] not null default '{}',
  script jsonb,
  -- scene / character key -> Storage path
  images jsonb not null default '{}'::jsonb,
  created_by text default auth.uid()::text references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index chronicle_episodes_campaign_idx on public.chronicle_episodes (campaign_id);
create trigger chronicle_episodes_touch before update on public.chronicle_episodes for each row execute function public.touch_updated_at();
alter table public.chronicle_episodes enable row level security;
create policy chronicle_episodes_read on public.chronicle_episodes for select to authenticated using (public.is_gm(campaign_id));
-- The author is whoever creates it.
create policy chronicle_episodes_insert on public.chronicle_episodes for insert to authenticated with check (public.is_gm(campaign_id) and created_by = public.me());
create policy chronicle_episodes_update on public.chronicle_episodes for update to authenticated using (public.is_gm(campaign_id)) with check (public.is_gm(campaign_id));
create policy chronicle_episodes_delete on public.chronicle_episodes for delete to authenticated using (public.is_gm(campaign_id));

-- ---------------------------------------------------------------------------
-- AI spend: anyone can make a campaign (and be its GM), so the AI routes take
-- a daily allowance per person, counted here by the server before each call.
-- ---------------------------------------------------------------------------

create table public.chronicle_usage (
  user_id text not null references public.profiles (id) on delete cascade,
  day date not null default current_date,
  kind text not null check (kind in ('script', 'image')),
  count integer not null default 0,
  primary key (user_id, day, kind)
);
alter table public.chronicle_usage enable row level security;
create policy chronicle_usage_own on public.chronicle_usage for select to authenticated using (user_id = public.me());

-- Counts one AI call for the caller, if they are a GM of the campaign and still
-- have allowance today (scripts: 20, images: 120). False when the day's allowance is used up.
create function public.spend_chronicle_quota(cid text, what text) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  allowance integer := case what when 'script' then 20 when 'image' then 120 else 0 end;
  used integer;
begin
  if not public.is_gm(cid) then raise exception 'Só os mestres da campanha criam episódios.' using errcode = '42501'; end if;
  if allowance = 0 then raise exception 'Uso desconhecido.' using errcode = '22023'; end if;
  insert into chronicle_usage (user_id, kind, count) values (auth.uid()::text, what, 1)
    on conflict (user_id, day, kind) do update set count = chronicle_usage.count + 1
    returning count into used;
  if used > allowance then
    update chronicle_usage set count = count - 1 where user_id = auth.uid()::text and day = current_date and kind = what;
    return false;
  end if;
  return true;
end $$;
revoke execute on function public.spend_chronicle_quota(text, text) from public, anon;
grant execute on function public.spend_chronicle_quota(text, text) to authenticated;

-- Images: private bucket, one folder per campaign (`<campaign_id>/<episode_id>/<key>.png`).
do $$
begin
  if to_regclass('storage.objects') is null then return; end if;
  -- Images only, up to 10 MB each.
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('chronicles', 'chronicles', false, 10485760, array['image/png', 'image/jpeg', 'image/webp'])
    on conflict (id) do update set file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
  execute $p$create policy chronicles_gm_read on storage.objects for select to authenticated
    using (bucket_id = 'chronicles' and public.is_gm((storage.foldername(name))[1]))$p$;
  execute $p$create policy chronicles_gm_insert on storage.objects for insert to authenticated
    with check (bucket_id = 'chronicles' and public.is_gm((storage.foldername(name))[1]))$p$;
  execute $p$create policy chronicles_gm_update on storage.objects for update to authenticated
    using (bucket_id = 'chronicles' and public.is_gm((storage.foldername(name))[1]))$p$;
  execute $p$create policy chronicles_gm_delete on storage.objects for delete to authenticated
    using (bucket_id = 'chronicles' and public.is_gm((storage.foldername(name))[1]))$p$;
end $$;


-- ===== 20261108000000_map_images_and_audio.sql =====

-- Role Quest — shared map pictures and the table's audio library.
--
-- Map pictures move from each GM's browser to Storage (`map-images`), so the
-- players see the imported map too. The audio centre's uploaded tracks live
-- in `table-audio`, listed in campaign_audio_tracks. Both buckets are private
-- with one folder per campaign, written by GMs. Members hear every track, but
-- see a map picture only once it is on the players' map: GMs may prepare maps
-- the players must not peek at.

create table public.campaign_audio_tracks (
  id text primary key default gen_random_uuid()::text,
  campaign_id text not null references public.campaigns (id) on delete cascade,
  title text not null check (char_length(title) between 1 and 120),
  path text not null,
  mime_type text not null,
  created_by text default auth.uid()::text references public.profiles (id) on delete set null,
  created_at timestamptz not null default now()
);
create index campaign_audio_tracks_campaign_idx on public.campaign_audio_tracks (campaign_id);
alter table public.campaign_audio_tracks enable row level security;
create policy audio_tracks_read on public.campaign_audio_tracks for select to authenticated using (public.is_member(campaign_id));
-- The file must sit in the campaign's folder.
create policy audio_tracks_insert on public.campaign_audio_tracks for insert to authenticated
  with check (public.is_gm(campaign_id) and created_by = public.me() and split_part(path, '/', 1) = campaign_id);
create policy audio_tracks_delete on public.campaign_audio_tracks for delete to authenticated using (public.is_gm(campaign_id));

-- True when the picture at `path` may be shown to the caller.
create function public.can_see_map_image(path text) returns boolean language sql stable security definer set search_path = public as $$
  select public.is_gm(split_part(path, '/', 1))
    or (public.is_member(split_part(path, '/', 1)) and exists (
      select 1 from room_view_maps v where v.campaign_id = split_part(path, '/', 1) and v.map -> 'background' ->> 'imageId' = path))
$$;

do $$
begin
  if to_regclass('storage.objects') is null then return; end if;
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('map-images', 'map-images', false, 15728640, array['image/png', 'image/jpeg', 'image/webp'])
    on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
  -- Same list as TRACK_TYPES in src/features/audio-engine/catalog.ts.
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('table-audio', 'table-audio', false, 26214400, array['audio/mpeg', 'audio/mp3', 'audio/ogg', 'audio/wav', 'audio/x-wav', 'audio/webm', 'audio/mp4', 'audio/aac', 'audio/x-m4a', 'audio/flac'])
    on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

  -- GMs add, replace and remove; members read tracks and the map on the table.
  execute $p$create policy campaign_audio_read on storage.objects for select to authenticated
    using (bucket_id = 'table-audio' and public.is_member((storage.foldername(name))[1]))$p$;
  execute $p$create policy campaign_map_image_read on storage.objects for select to authenticated
    using (bucket_id = 'map-images' and public.can_see_map_image(name))$p$;
  execute $p$create policy campaign_media_insert on storage.objects for insert to authenticated
    with check (bucket_id in ('map-images', 'table-audio') and public.is_gm((storage.foldername(name))[1]))$p$;
  execute $p$create policy campaign_media_update on storage.objects for update to authenticated
    using (bucket_id in ('map-images', 'table-audio') and public.is_gm((storage.foldername(name))[1]))$p$;
  execute $p$create policy campaign_media_delete on storage.objects for delete to authenticated
    using (bucket_id in ('map-images', 'table-audio') and public.is_gm((storage.foldername(name))[1]))$p$;
end $$;


-- ===== 20261110000000_voice_chat.sql =====

-- Role Quest — voice chat at the table.
--
-- Members talk over WebRTC, straight between browsers. To find each other they
-- exchange small signalling messages on a private Realtime broadcast channel
-- named "voice:<campaign id>". These policies (Realtime Authorization) let only
-- members of that campaign join the channel, send on it and hear it.

create policy voice_members_receive on realtime.messages for select to authenticated
  using (
    realtime.messages.extension = 'broadcast'
    and realtime.topic() like 'voice:%'
    and public.is_member(substr(realtime.topic(), 7))
  );

create policy voice_members_send on realtime.messages for insert to authenticated
  with check (
    realtime.messages.extension = 'broadcast'
    and realtime.topic() like 'voice:%'
    and public.is_member(substr(realtime.topic(), 7))
  );


-- ===== 20261111000000_chronicles_sharing.sql =====

-- Role Quest — Chronicles: narration and episodes shared with the players.
--
-- * `voices`: recorded narration per scene (Storage path, the caption it reads
--   and its length), next to the images in the private `chronicles` bucket.
-- * `published_at`: when the GM shared the episode. The campaign's players can
--   then watch it (video and comic), read-only, with its images and narration;
--   unpublished episodes stay with the GMs.
-- * A daily allowance for narration clips, like scripts and images.

alter table public.chronicle_episodes
  add column voices jsonb not null default '{}'::jsonb,
  add column published_at timestamptz;

drop policy chronicle_episodes_read on public.chronicle_episodes;
create policy chronicle_episodes_read on public.chronicle_episodes for select to authenticated
  using (public.is_gm(campaign_id) or (published_at is not null and public.is_member(campaign_id)));
-- Writing stays with the GMs (insert / update / delete policies unchanged): players can't share or unshare.

-- A file of the bucket (`<campaign>/<episode>/<key>.<ext>`) is readable by the
-- campaign's GMs, and by its members when a shared episode of that campaign uses it.
create function public.can_see_chronicle_file(path text) returns boolean language sql stable security definer set search_path = public as $$
  select public.is_gm(split_part(path, '/', 1))
    or (public.is_member(split_part(path, '/', 1)) and exists (
      select 1 from chronicle_episodes e
      where e.campaign_id = split_part(path, '/', 1) and e.published_at is not null
        and (exists (select 1 from jsonb_each_text(e.images) i where i.value = path)
          or exists (select 1 from jsonb_each(e.voices) v where v.value ->> 'ref' = path))))
$$;
revoke execute on function public.can_see_chronicle_file(text) from public, anon;
grant execute on function public.can_see_chronicle_file(text) to authenticated;

-- Narration clips count against their own daily allowance (200 a day).
alter table public.chronicle_usage drop constraint chronicle_usage_kind_check;
alter table public.chronicle_usage add constraint chronicle_usage_kind_check check (kind in ('script', 'image', 'voice'));

create or replace function public.spend_chronicle_quota(cid text, what text) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  allowance integer := case what when 'script' then 20 when 'image' then 120 when 'voice' then 200 else 0 end;
  used integer;
begin
  if not public.is_gm(cid) then raise exception 'Só os mestres da campanha criam episódios.' using errcode = '42501'; end if;
  if allowance = 0 then raise exception 'Uso desconhecido.' using errcode = '22023'; end if;
  insert into chronicle_usage (user_id, kind, count) values (auth.uid()::text, what, 1)
    on conflict (user_id, day, kind) do update set count = chronicle_usage.count + 1
    returning count into used;
  if used > allowance then
    update chronicle_usage set count = count - 1 where user_id = auth.uid()::text and day = current_date and kind = what;
    return false;
  end if;
  return true;
end $$;

-- Storage: narration (WAV) joins the images; members read what shared episodes use.
do $$
begin
  if to_regclass('storage.objects') is null then return; end if;
  update storage.buckets set allowed_mime_types = array['image/png', 'image/jpeg', 'image/webp', 'audio/wav'] where id = 'chronicles';
  drop policy if exists chronicles_gm_read on storage.objects;
  execute $p$create policy chronicles_read on storage.objects for select to authenticated
    using (bucket_id = 'chronicles' and public.can_see_chronicle_file(name))$p$;
end $$;


-- ===== 20261112000000_launch.sql =====

-- Launch: account deletion (LGPD), plans and AI credits, session reminders.
--
-- Plans are written only by the billing webhook (service role). Limits apply
-- once billing is switched on: `update billing_config set enforce = true;`
-- Until then everyone keeps the paid allowances (nobody can pay yet).

-- ---------------------------------------------------------------------------
-- Account deletion: the user's campaigns go first (their members would block
-- a cascade from the profile), then the profile, then the auth user.
-- Files in Storage under those campaigns are removed by the API route.
-- ---------------------------------------------------------------------------

create function public.delete_my_account() returns void
language plpgsql security definer set search_path = public as $$
declare
  uid text := auth.uid()::text;
begin
  if uid is null then raise exception 'Entre na sua conta para excluí-la.' using errcode = '42501'; end if;
  delete from campaigns where owner_id = uid;
  delete from profiles where id = uid;
  delete from auth.users where id = uid::uuid;
end $$;
revoke execute on function public.delete_my_account() from public, anon;
grant execute on function public.delete_my_account() to authenticated;

-- ---------------------------------------------------------------------------
-- Plans
-- ---------------------------------------------------------------------------

create table public.billing_config (
  id boolean primary key default true check (id),
  enforce boolean not null default false
);
insert into public.billing_config default values;
alter table public.billing_config enable row level security;
create policy billing_config_read on public.billing_config for select to authenticated, anon using (true);

create table public.subscriptions (
  user_id text primary key references public.profiles (id) on delete cascade,
  plan text not null check (plan in ('free', 'mestre', 'mesa')),
  status text not null default 'active',
  current_period_end timestamptz,
  cancel_at_period_end boolean not null default false,
  stripe_customer_id text unique,
  stripe_subscription_id text unique,
  updated_at timestamptz not null default now()
);
alter table public.subscriptions enable row level security;
create policy subscriptions_own on public.subscriptions for select to authenticated using (user_id = auth.uid()::text);

create table public.ai_credits (
  user_id text primary key references public.profiles (id) on delete cascade,
  balance integer not null default 0 check (balance >= 0),
  updated_at timestamptz not null default now()
);
alter table public.ai_credits enable row level security;
create policy ai_credits_own on public.ai_credits for select to authenticated using (user_id = auth.uid()::text);

-- Stripe events already handled (the webhook may deliver one twice).
create table public.billing_events (
  id text primary key,
  received_at timestamptz not null default now()
);
alter table public.billing_events enable row level security;

create function public.billing_enforced() returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select enforce from billing_config), false)
$$;

/** The plan a user has now: a paid one while the subscription is active, else free (or "mestre" before billing is on). */
create function public.plan_of(uid text) returns text language sql stable security definer set search_path = public as $$
  select case
    when not public.billing_enforced() then 'mestre'
    else coalesce(
      (select plan from subscriptions
        where user_id = uid and status in ('active', 'trialing', 'past_due')
          and (current_period_end is null or current_period_end > now() - interval '3 days')),
      'free')
  end
$$;
grant execute on function public.plan_of(text) to authenticated;

create function public.my_plan() returns text language sql stable security definer set search_path = public as $$
  select public.plan_of(auth.uid()::text)
$$;
grant execute on function public.my_plan() to authenticated;

/** Daily AI allowance per plan; credits pay for what goes over (script 5, image 1, voice 1). */
create or replace function public.spend_chronicle_quota(cid text, what text) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  plan text := public.plan_of(auth.uid()::text);
  allowance integer := case what
    when 'script' then case plan when 'free' then 3 when 'mesa' then 40 else 20 end
    when 'image' then case plan when 'free' then 30 when 'mesa' then 240 else 120 end
    when 'voice' then case plan when 'free' then 40 when 'mesa' then 400 else 200 end
    else 0 end;
  price integer := case what when 'script' then 5 else 1 end;
  used integer;
begin
  if not public.is_gm(cid) then raise exception 'Só os mestres da campanha criam episódios.' using errcode = '42501'; end if;
  if allowance = 0 then raise exception 'Uso desconhecido.' using errcode = '22023'; end if;
  insert into chronicle_usage (user_id, kind, count) values (auth.uid()::text, what, 1)
    on conflict (user_id, day, kind) do update set count = chronicle_usage.count + 1
    returning count into used;
  if used <= allowance then return true; end if;
  -- Over the allowance: credits, if there are enough.
  update ai_credits set balance = balance - price, updated_at = now()
    where user_id = auth.uid()::text and balance >= price;
  if found then return true; end if;
  update chronicle_usage set count = count - 1 where user_id = auth.uid()::text and day = current_date and kind = what;
  return false;
end $$;

/** What the account page shows: plan, renewal, credits and today's use. */
create function public.my_billing() returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'plan', public.plan_of(auth.uid()::text),
    'enforced', public.billing_enforced(),
    'status', (select status from subscriptions where user_id = auth.uid()::text),
    'renewsAt', (select current_period_end from subscriptions where user_id = auth.uid()::text),
    'cancelAtPeriodEnd', coalesce((select cancel_at_period_end from subscriptions where user_id = auth.uid()::text), false),
    'credits', coalesce((select balance from ai_credits where user_id = auth.uid()::text), 0),
    'usedToday', coalesce((select jsonb_object_agg(kind, count) from chronicle_usage where user_id = auth.uid()::text and day = current_date), '{}'::jsonb)
  )
$$;
grant execute on function public.my_billing() to authenticated;

-- Free plan: one campaign under way at a time (finished ones don't count).
create function public.guard_campaign_limit() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.plan_of(new.owner_id) = 'free'
    and (select count(*) from campaigns where owner_id = new.owner_id and status <> 'completed') >= 1 then
    raise exception 'O plano grátis tem uma campanha em andamento por vez. Conclua a atual ou assine o plano Mestre.' using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger campaigns_plan_limit before insert on public.campaigns for each row execute function public.guard_campaign_limit();

-- ---------------------------------------------------------------------------
-- Session reminders: what was already sent (the cron job runs every hour).
-- ---------------------------------------------------------------------------

create table public.session_reminders (
  session_id text not null references public.game_sessions (id) on delete cascade,
  user_id text not null references public.profiles (id) on delete cascade,
  sent_at timestamptz not null default now(),
  primary key (session_id, user_id)
);
alter table public.session_reminders enable row level security;

alter table public.profiles add column email_reminders boolean not null default true;


commit;
